"""Fix 1: multi-strategy MEDLINE — is the 43% miss an artifact of a narrow obesity-weight string?
Compare the NARROW (obesity+weight) search to a BROAD (diabetes-inclusive) search, plus note that
ghosts are unfindable by ANY search ([si]-confirmed). Coverage via AACT study_references (a lower
bound, since AACT linkage is ~incomplete). PubMed only.
"""
import io, sys, json
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8', errors='replace')
import pandas as pd
from aact_kit import load_table, location_from_path

