mc = pd.read_csv(f'{ROOT}/medline_compare.csv').set_index('nct')  # has narrow medline_found
cohort = sorted(mc.index)
sr = load_table('study_references', location=LOC, columns=['nct_id', 'pmid', 'reference_type'])
sr = sr[sr.nct_id.isin(cohort) & sr.pmid.notna()].copy()
sr['pmid'] = sr['pmid'].astype('Int64').astype(str)
nct_pmids = sr.groupby('nct_id')['pmid'].apply(set).to_dict()

found_narrow = int(mc['medline_found'].sum())
found_broad = sum(1 for n in cohort if (nct_pmids.get(n, set()) & BROAD))
n = len(cohort)
print(f'cohort: {n} trials. MEDLINE coverage via AACT linkage (lower bound):')
print(f'  NARROW (obesity+weight) search (200 hits): finds {found_narrow}/{n} ({100*found_narrow/n:.0f}%)')
print(f'  BROAD (diabetes-inclusive) search (391 hits): finds {found_broad}/{n} ({100*found_broad/n:.0f}%)')
print(f'  -> a diabetes-inclusive search recovers {found_broad-found_narrow} of the missed trials '
      f'(the T2D trials indexed under diabetes).')
still_missed = [nm for nm in cohort if not (nct_pmids.get(nm, set()) & BROAD)]
print(f'\n  STILL missed by the BROAD search: {n-found_broad}/{n}')
g = [m for m in still_missed if m in GHOSTS]
print(f'    of which unpublished ghosts ([si]-confirmed, unfindable by ANY search): {len(g)}')
print(f'    others (AACT-unlinked / non-MEDLINE / no result): {len(still_missed)-len(g)}')

print('\n=== honest reframe (Fix 1) ===')
print(' - The 43% NARROW miss is partly search-strategy-dependent: a diabetes-inclusive search')
print('   recovers the published T2D trials. So "literature misses 43%/0% diabetes" must be stated as')
print('   "an OBESITY-SCOPED search/SR (what is actually published, e.g. Xie 2024) misses them by design".')
print(' - What is irreducible and registry-only: the ~%d unpublished ghosts no search can find (%.0f%% of cohort),' % (len(GHOSTS), 100*len(GHOSTS)/n))
print('   plus robustness to which search string the analyst happens to choose.')
print(' - Caveat: coverage uses AACT PMID linkage (incomplete ~40%), so these are LOWER bounds on findability;')
print('   ghost status is the firmer claim ([si]-confirmed direct PubMed absence).')
json.dump({'cohort': n, 'found_narrow': found_narrow, 'found_broad': found_broad,
           'still_missed_broad': n - found_broad, 'ghosts_irreducible': len(g)},
          open(f'{ROOT}/medline_multistrategy.json', 'w'), indent=1)
print('\nwrote medline_multistrategy.json')
